/** Writes one `TehillimUnit` to a value buffer. */
inline void write_TehillimUnit(BufferWriter& w, const TehillimUnit& v) {
    switch (v.value.index()) {
        case 0: {
            w.write_i32(0);
            const TehillimUnit::Psalms& p = std::get<0>(v.value);
            w.write_i32(p.start);
            w.write_i32(p.end);
            break;
        }
        case 1: {
            w.write_i32(1);
            const TehillimUnit::PsalmVerses& p = std::get<1>(v.value);
            w.write_i32(p.psalm);
            w.write_i32(p.start_verse);
            w.write_i32(p.end_verse);
            break;
        }
    }
}

/** Reads one `TehillimUnit` from a value buffer. */
inline TehillimUnit read_TehillimUnit(BufferReader& r) {
    int32_t tag = r.read_i32();
    switch (tag) {
        case 0:
            return TehillimUnit{TehillimUnit::Psalms{
                r.read_i32(),
                r.read_i32(),
            }};
        case 1:
            return TehillimUnit{TehillimUnit::PsalmVerses{
                r.read_i32(),
                r.read_i32(),
                r.read_i32(),
            }};
        default: break;
    }
    BufferReader::fail("unknown TehillimUnit tag");
}

