inline void write_PirkeiAvosUnit(BufferWriter& w, const PirkeiAvosUnit& v) {
    switch (v.value.index()) {
        case 0: {
            w.write_i32(0);
            const PirkeiAvosUnit::Single& p = std::get<0>(v.value);
            w.write_i32(p.chapter);
            break;
        }
        case 1: {
            w.write_i32(1);
            const PirkeiAvosUnit::Combined& p = std::get<1>(v.value);
            w.write_i32(p.first);
            w.write_i32(p.second);
            break;
        }
    }
}

/** Reads one `PirkeiAvosUnit` from a value buffer. */
inline PirkeiAvosUnit read_PirkeiAvosUnit(BufferReader& r) {
    int32_t tag = r.read_i32();
    switch (tag) {
        case 0:
            return PirkeiAvosUnit{PirkeiAvosUnit::Single{
                r.read_i32(),
            }};
        case 1:
            return PirkeiAvosUnit{PirkeiAvosUnit::Combined{
                r.read_i32(),
                r.read_i32(),
            }};
        default: break;
    }
    BufferReader::fail("unknown PirkeiAvosUnit tag");
}

